{
  "case_id": "C08",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook",
      "narration": "Once you've fought off an infection, your immune system doesn't just go back to how it was. It keeps something behind.",
      "on_screen": "A virus particle fading out; a few immune cells remain glowing in the bloodstream.",
      "claim_refs": ["SYN-C08:background"]
    },
    {
      "beat": "What memory T cells are",
      "narration": "Some of the T cells that recognised that specific germ survive as a memory population, ready to respond again.",
      "on_screen": "Labelled animation: antigen-specific memory CD8+ T cells persisting after infection clears.",
      "claim_refs": ["SYN-C08:background"]
    },
    {
      "beat": "How long they last",
      "narration": "In a review of 302 adults tracking one viral target, these memory cells were still detectable in 88 percent of people after five years, and in 61 percent after twelve.",
      "on_screen": "Two bars: 5 years, 88%; 12 years, 61%. Small print: n=302, MHC-multimer staining.",
      "claim_refs": ["SYN-C08:results:detectable_5y", "SYN-C08:results:detectable_12y"]
    },
    {
      "beat": "How much faster",
      "narration": "And when the immune system met that target again, it expanded 4.2 times faster than the first time round.",
      "on_screen": "Two response curves side by side; the second rises steeply. Caption: 4.2x faster, 95% CI 3.1 to 5.7.",
      "claim_refs": ["SYN-C08:results:secondary_expansion"]
    },
    {
      "beat": "The filing cabinet, and where it breaks",
      "narration": "People often call this a filing cabinet: the body keeps a folder on each germ. That works for speed. It breaks down after that. There's no index, nothing is looked up on demand, and the folders fade, as those five and twelve year numbers show.",
      "on_screen": "A filing cabinet illustration; drawers dissolve, labels peel away.",
      "claim_refs": ["SYN-C08:teaching_note"]
    },
    {
      "beat": "Caveat and close",
      "narration": "Detectable memory cells also don't guarantee you won't get ill, and these figures are for one virus target and vary from person to person. Real immune memory is faster, but far messier than a filing cabinet.",
      "on_screen": "Text: 'Detection is not protection. One epitope; varies by pathogen and person.'",
      "claim_refs": ["SYN-C08:teaching_note", "SYN-C08:limitations", "SYN-C08:methods"]
    }
  ]
}
